            secondJointPoseABS0 = util.TransformationRobotToABS(secondJointPoseRobot0, posture)
        
            if secondJointPoseABS0[2] < ground_z:
                theta1_0 = theta2_0 = theta3_0 = 1000
            
            # 20251214
            try:
                theta3_1 = -math.acos((x**2+y**2+z**2-self.__L[2]**2-self.__L[3]**2) / (2*self.__L[2]*self.__L[3]))
                theta1_1 = math.atan2(y, x)
                theta2_1 = math.atan2(-self.__L[3]*math.sin(theta3_1)*math.sqrt(x**2+y**2) + (self.__L[2]+self.__L[3]*math.cos(theta3_1))*z, 
                                    (self.__L[2]+self.__L[3]*math.cos(theta3_1))*math.sqrt(x**2+y**2) +  self.__L[3]*math.sin(theta3_1)*z)
            except Exception as e:
                print(e)
